from e14c.web import fetch_paper
paper_dois=["10.1208/s12249-021-02104-9","10.1208/s12249-020-01835-5","10.3390/electronics9060995","10.1038/s41598-024-72288-0","10.1016/j.powtec.2014.01.062"]
papers={}
for doi in paper_dois:
    try:
        p=await fetch_paper(doi=doi)
        papers[doi]=p
        txt='\n'.join(pg.get('text','') for pg in p.get('pages',[]))
        print(doi,'pages',len(p.get('pages',[])),'chars',len(txt))
        for term in ['relative standard deviation','RSD','shut','stop','discharge','feed rate','accuracy','bulk','fine','dribble','in-flight']:
            if term.lower() in txt.lower(): print(' has',term)
    except Exception as e: print(doi,type(e).__name__,str(e)[:200])

# Extract context passages from retrieved papers around relevant terms.
for doi,p in papers.items():
    txt='\n'.join(pg.get('text','') for pg in p.get('pages',[]))
    print('\n\n###',doi)
    for pattern in ['relative standard deviation','low feed rate','stop feeding','stopped','discharge rate','refill','accuracy']:
        matches=list(re.finditer(pattern,txt,re.I))
        if matches:
            print('\n--',pattern,'--')
            for m in matches[:3]:
                print(re.sub(r'\s+',' ',txt[max(0,m.start()-300):m.end()+500])[:900])

extra_q = [
 "two stage bulk dribble gravimetric filling cutoff weight compensation inflight material",
 "powder filling machine coarse fine feed cutoff weight compensation free fall correction",
 "auger feeder shutdown residual discharge post stop powder outlet",
 "screw feeder stopping response residual flow after screw stops"
]
extra={}
for q in extra_q:
    extra[q]=await web_search(q,num_results=10)
    print('\n',q)
    for r in extra[q][:10]: print(r.get('title'),r.get('url'))
